library(GEOquery); library(robustbase)
out<-normalizePath("outputs",mustWork=TRUE); sc<-read.csv(file.path(out,"mechanism_module_scores.csv"),check.names=FALSE); sc<-subset(sc,dataset=="GSE32537")
es<-getGEO(filename=file.path("inputs/geo_series_matrix","GSE32537_series_matrix.txt.gz"),GSEMatrix=TRUE,getGPL=FALSE); pd<-pData(es); rownames(pd)<-pd$geo_accession; cc<-pd[,grep("^characteristics",names(pd)),drop=FALSE]
getf<-function(p,n=FALSE){z<-apply(cc,1,function(x){y<-x[grepl(p,tolower(x))];if(length(y))y[1]else NA_character_});z<-sub("^[^:]*:\\s*","",z);if(n)as.numeric(sub("[^0-9.-].*$","",z))else factor(z)}
meta<-data.frame(sample_id=rownames(pd),age=getf("^age",TRUE),gender=getf("^gender"),smoking=getf("smoking status"),rin=getf("^rin",TRUE),tissue=getf("tissue source")); d<-merge(sc,meta,by="sample_id",sort=FALSE);d$case<-factor(ifelse(d$group=="IPF_UIP","IPF_UIP",ifelse(d$group=="control","control",NA)),levels=c("control","IPF_UIP"));mods<-c("epithelial_barrier","mucociliary_clearance","injury_inflammation","oxidative_stress","fibrosis_epithelial_response");rows<-lapply(mods,function(m){z<-d[!is.na(d$case),c(m,"case","age","gender","smoking","rin")];z<-z[complete.cases(z),,drop=FALSE];fit<-lmrob(as.formula(paste(m,"~ case+age+gender+smoking+rin")),data=z);co<-summary(fit)$coefficients["caseIPF_UIP",];data.frame(outcome=m,n=nrow(z),beta=co[1],se=co[2],t=co[3],p=co[4],stringsAsFactors=FALSE)});r<-do.call(rbind,rows);r$fdr<-p.adjust(r$p,"BH");write.csv(r,file.path(out,"robust_lmrob_no_tissue_source_GSE32537.csv"),row.names=FALSE,fileEncoding="UTF-8");capture.output({cat("Robust lmrob sensitivity using the prespecified no-tissue-source model; no donor ID available in GEO metadata.\n");print(r)},file=file.path(out,"robust_lmrob_no_tissue_source_report.txt"))
